<script setup>
import { onMounted, reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { state, api, refreshUser, logout, notify } from '../lib/store.js'
import { personData, personFields } from '../lib/catalog.js'
import ValidatedForm from '../components/ValidatedForm.vue'
import Field from '../components/Field.vue'
import Notices from '../components/Notices.vue'
import PasswordForm from '../components/PasswordForm.vue'
import OrdersList from '../components/OrdersList.vue'
const router = useRouter(), editing = ref(false), passwordOpen = ref(false), form = reactive(personData(state.user)), orders = ref([]), error = ref(''), loading = ref(true), busy = ref(false)
onMounted(async () => { if (!state.user) return router.replace('/login'); try { await refreshUser(); Object.assign(form, personData(state.user)); orders.value = (await api('/orders')).sort((a,b) => new Date(b.createdAt) - new Date(a.createdAt)) } catch (e) { error.value = e.message } finally { loading.value = false } })
function edit() { Object.assign(form, personData(state.user)); editing.value = true; error.value = '' }
async function save() { busy.value = true; error.value = ''; try { await api('/me', { method: 'PUT', body: { ...form } }); await refreshUser(); editing.value = false; notify('Deine Daten wurden gespeichert.') } catch (e) { error.value = e.message } finally { busy.value = false } }
async function leave() { try { await logout(); router.push('/') } catch (e) { error.value = e.message } }
async function remove() { if (!window.confirm('Möchtest du dein Konto wirklich löschen? Bereits aufgegebene Bestellungen bleiben erhalten und können weiter bearbeitet werden. Du kannst danach nicht mehr über dein Konto darauf zugreifen.')) return; busy.value = true; try { await api('/me', { method: 'DELETE' }); state.user = null; state.wishlist = []; state.cart = []; await router.push('/'); notify('Dein Konto wurde gelöscht.') } catch (e) { error.value = e.message } finally { busy.value = false } }
function updateOrder(order) { orders.value = orders.value.map(o => o.id === order.id ? order : o) }
</script>
<template><section v-if="state.user" class="page"><div class="page-intro"><span class="eyebrow">DEIN BENUTZERKONTO</span><h1>Hallo, {{ state.user.firstName }}<span class="heading-dot">.</span></h1><p>Schön, dich wiederzusehen.</p></div><div class="account-layout"><nav class="account-nav" aria-label="Benutzerkonto"><a href="#persoenliche-daten">Persönliche Daten</a><a href="#meine-bestellungen">Meine Bestellungen</a><RouterLink to="/wunschliste">Meine Wunschliste</RouterLink><button @click="passwordOpen = !passwordOpen">Passwort ändern</button><button @click="leave">Abmelden</button><button class="danger" :disabled="busy" @click="remove">Konto löschen</button></nav><div class="account-content"><Notices :busy="loading" :error="error" /><section id="persoenliche-daten" class="account-section"><div class="section-toolbar"><h2>Persönliche Daten</h2><button v-if="!editing" class="text-button" @click="edit">Bearbeiten</button></div><ValidatedForm v-if="editing" @submit="save"><div class="form-grid"><Field v-for="field in personFields" :key="field.name" v-model="form[field.name]" v-bind="field" :required="['firstName', 'lastName', 'email'].includes(field.name)" :class="{ 'span-2': field.name === 'street' || field.name === 'email' }" /></div><div class="row"><button class="button" :disabled="busy">Speichern</button><button type="button" class="text-button" @click="editing = false">Abbrechen</button></div></ValidatedForm><div v-else class="profile-data"><p><strong>{{ state.user.firstName }} {{ state.user.lastName }}</strong><br>{{ state.user.email }}</p><address v-if="Object.values(state.user.address || {}).some(Boolean)"><span v-if="state.user.address.street">{{ state.user.address.street }}<br></span><span v-if="state.user.address.postalCode || state.user.address.city">{{ state.user.address.postalCode }} {{ state.user.address.city }}<br></span><span v-if="state.user.address.country">{{ state.user.address.country }}</span></address></div></section><section v-if="passwordOpen" class="account-section"><h2>Passwort ändern</h2><PasswordForm /></section><section id="meine-bestellungen" class="account-section"><h2>Meine Bestellungen</h2><OrdersList v-if="orders.length" :orders="orders" @update="updateOrder" /><p v-else-if="!loading">Du hast noch keine Bestellungen.</p></section></div></div></section></template>
